// Manual fixture maintenance command; CI checks frozen values and never regenerates them.
import fs from "node:fs";
import { referenceHash, referenceVector } from "./shielded-receive-encryption.reference.js";

const utf8 = (value) => Buffer.from(value, "utf8");
const hexFields = (value) =>
  Object.fromEntries(
    Object.entries(value).map(([key, bytes]) => [key, Buffer.from(bytes).toString("hex")]),
  );
const cases = [
  {
    name: "zero-inputs-empty-message",
    viewIkm: Buffer.alloc(32),
    diversifier: Buffer.alloc(32),
    rseed: Buffer.alloc(32),
    plaintext: Buffer.alloc(0),
    aad: Buffer.alloc(0),
    info: Buffer.alloc(0),
  },
  {
    name: "high-bits-unicode-and-binary-message",
    viewIkm: Buffer.alloc(32, 255),
    diversifier: Buffer.alloc(32, 255),
    rseed: Buffer.from(Array.from({ length: 32 }, (_, i) => 255 - i)),
    plaintext: utf8("固定测试向量\0🧬"),
    aad: utf8("DeepFamily reference authenticated scope"),
    info: utf8("DeepFamily:ReceiveNote:v1"),
  },
  {
    name: "mixed-bytes-fixed-512-byte-ciphertext",
    viewIkm: referenceHash(utf8("DeepFamily receive vector 3 viewing seed")),
    diversifier: referenceHash(utf8("DeepFamily receive vector 3 diversifier")),
    rseed: referenceHash(utf8("DeepFamily receive vector 3 encryption seed")),
    plaintext: Buffer.from(Array.from({ length: 400 }, (_, i) => i & 255)),
    aad: utf8("DeepFamily reference chain/pool binding"),
    info: utf8("DeepFamily:PrivateLetterHPKE:v1"),
  },
];

const fixture = {
  version: 1,
  suite: "DeepFamily diversified receive encryption v1",
  provenance:
    "Synthetic public inputs. Computed by test-only noble Ristretto + independent Node crypto XMD/HKDF/AES-GCM. Frozen against the pre-WASM implementation; not generated by the production WASM backend.",
  vectors: cases.map(({ name, ...inputs }) => ({
    name,
    input: hexFields(inputs),
    expected: hexFields(referenceVector(inputs)),
  })),
};
fs.writeFileSync(
  new URL("./shielded-receive-encryption.vectors.json", import.meta.url),
  `${JSON.stringify(fixture, null, 2)}\n`,
);
